// CAPABILITY INTERFACE: Can be adopted by completely unrelated classes
interface Flyable {
    void fly(double altitude);
}

// BASE IDENTITY ABSTRACT CLASS: Holds biological state and enforces single inheritance
abstract class Bird {
    protected String species;
    protected double wingSpan;

    public Bird(String species, double wingSpan) {
        this.species = species;
        this.wingSpan = wingSpan;
    }
    public void layEgg() {
        System.out.println(species + " laid an egg.");
    }
}

// Eagle IS-A Bird and CAN-DO Fly
class Eagle extends Bird implements Flyable {
    public Eagle() { super("Bald Eagle", 2.1); }
    @Override
    public void fly(double altitude) {
        System.out.println(species + " soaring at " + altitude + "m with wingspan " + wingSpan + "m");
    }
}

// Drone is NOT a Bird, but CAN-DO Fly!
class Drone implements Flyable {
    @Override
    public void fly(double altitude) {
        System.out.println("Quadcopter rotors spinning to hold altitude: " + altitude + "m");
    }
}

public class ComparisonDemo {
    public static void main(String[] args) {
        Flyable[] airborne = new Flyable[] { new Eagle(), new Drone() };
        for (Flyable f : airborne) {
            f.fly(500.0);
        }
    }
}

