interface Stack {
    void push(int val);
    int pop();
    int peek();
    boolean isEmpty();
}

// Skeletal implementation providing common logic
abstract class AbstractStack implements Stack {
    @Override
    public boolean isEmpty() {
        return size() == 0; // Default implementation using size()
    }
    public abstract int size();
}

// Concrete stack implementing remaining methods
class ArrayStack extends AbstractStack {
    private int[] data = new int[10];
    private int top = 0;

    @Override public void push(int val) { data[top++] = val; }
    @Override public int pop() { return data[--top]; }
    @Override public int peek() { return data[top - 1]; }
    @Override public int size() { return top; }
}

public class StackDemo {
    public static void main(String[] args) {
        Stack s = new ArrayStack();
        s.push(100);
        s.push(200);
        System.out.println("Peek: " + s.peek() + " | IsEmpty: " + s.isEmpty());
    }
}

