}

interface Swimmable {
    void swim();
}

class Duck extends Animal implements Swimmable {
    public Duck(String name) {
        super(name);
    }
    @Override
    public void makeSound() {
        System.out.println(name + " says Quack!");
    }
    @Override
    public void swim() {
        System.out.println(name + " is paddling on the pond");
    }
}

public class DuckApp {
    public static void main(String[] args) {
        Duck duck = new Duck("Donald");
        duck.makeSound();
        duck.swim();
    }
}

import java.util.Map;
import java.util.HashMap;

interface CacheStore {
    void put(String k, String v);
    String get(String k);
    boolean contains(String k);
}

abstract class AbstractCacheStore implements CacheStore {
    @Override
    public boolean contains(String k) {
        return get(k) != null;
    }
}

class InMemoryCache extends AbstractCacheStore {
    private Map<String, String> map = new HashMap<>();
    @Override
    public void put(String k, String v) {
        map.put(k, v);
    }
    @Override
    public String get(String k) {
        return map.get(k);
    }
}

public class CacheApp {
    public static void main(String[] args) {
        CacheStore cache = new InMemoryCache();
        cache.put("session", "active");
        System.out.println("Session: " + cache.get("session"));
        System.out.println("Contains: " + cache.contains("session"));
    }
}

interface Filterable {
    boolean shouldProcess(String req);
}

abstract class BaseFilter implements Filterable {
    protected String filterName;
    public BaseFilter(String filterName) {
        this.filterName = filterName;
    }
    public void logCheck(String req) {
        System.out.println("[" + filterName + "] Inspecting: " + req);
    }
}

class AuthTokenFilter extends BaseFilter {
    public AuthTokenFilter(String name) {
        super(name);
    }
    @Override
    public boolean shouldProcess(String req) {
        logCheck(req);
        return req.contains("Bearer ");
    }
}

public class FilterApp {
    public static void main(String[] args) {
        Filterable filter = new AuthTokenFilter("JWT-Auth");
        boolean allowed = filter.shouldProcess("GET /api/data Bearer xyz");
        System.out.println("Allowed: " + allowed);
    }
}

