        gw.increment();
    }
}

import java.util.Map;
import java.util.HashMap;

interface BlobStorage {
    void upload(String path, String data);
    String download(String path);
}

interface Encryptable {
    String encrypt(String raw);
    String decrypt(String cipher);
}

abstract class AbstractStorageProvider implements BlobStorage, Encryptable {
    protected String providerName;
    public AbstractStorageProvider(String providerName) {
        this.providerName = providerName;
    }
    public void audit(String action, String path) {
        System.out.println("[" + providerName + "] " + action + " on: " + path);
    }
}

class SecureCloudStore extends AbstractStorageProvider {
    private Map<String, String> disk = new HashMap<>();
    public SecureCloudStore() {
        super("AWS-KMS-S3");
    }
    @Override
    public String encrypt(String raw) {
        return "[ENC:" + raw + "]";
    }
    @Override
    public String decrypt(String cipher) {
        return cipher.replace("[ENC:", "").replace("]", "");
    }
    @Override
    public void upload(String path, String data) {
        audit("UPLOAD", path);
        disk.put(path, encrypt(data));
    }
    @Override
    public String download(String path) {
        audit("DOWNLOAD", path);
        String cipher = disk.get(path);
        return decrypt(cipher);
    }
}

public class StorageEnterpriseApp {
    public static void main(String[] args) {
        BlobStorage storage = new SecureCloudStore();
        storage.upload("config.json", "secret_token_99");
        String result = storage.download("config.json");
        System.out.println("Retrieved: " + result);
    }
}
